import {validateModel} from './floorplan-model-core.mjs';
const $=id=>document.getElementById(id);let project=null,model=null,modelRevision=1,viewer=null,viewerPromise=null,busy=false,dirty=false,version=0,urls=[];const message=s=>$('model-status').textContent=s;let projects=[];
function ready(){const has=!!model;for(const id of ['model-save','view-reset','view-top','auto-rotate','show-furniture','wall-cut','model-snapshot','model-export','apply-dimensions','apply-model-json'])$(id).disabled=busy||!has;$('model-generate').disabled=busy||!project;$('model-project').disabled=busy;$('model-consent').disabled=busy;for(const id of ['model-width','model-depth','model-height','model-json'])$(id).disabled=busy}
async function ensureViewer(){if(viewer)return viewer;viewerPromise||=import('./floorplan-viewer.mjs?v=2').then(m=>{viewer=m.createViewer($('model-view'));return viewer}).catch(e=>{viewerPromise=null;throw Error('Die 3D-Ansicht konnte nicht geladen werden. Bitte WebGL-2-Unterstützung und Verbindung prüfen. Modelldaten können trotzdem gespeichert werden.')});return viewerPromise}
async function show(next,reset=true){model=validateModel(next);$('model-json').value=JSON.stringify(model,null,2);$('model-width').value=model.width;$('model-depth').value=model.depth;$('model-height').value=model.height;$('wall-cut').max=model.height;const cut=Math.min(Number($('wall-cut').value)||1.2,model.height);$('wall-cut').value=cut;$('wall-cut-label').textContent=cut.toLocaleString('de-DE')+' m';$('model-notes').textContent='Ungeprüfte Rekonstruktion · '+model.rooms.length+' Räume · '+model.walls.length+' Wandsegmente\n'+model.notes;ready();const v=await ensureViewer();v.setCut(cut);v.setFurniture($('show-furniture').checked);v.build(model,{reset});v.rotate($('auto-rotate').checked)}
async function loadProject(id){if(dirty&&!confirm('Ungespeicherte Modelländerungen verwerfen?'))return;const token=++version;const p=id?await FloorplanStore.get(id):null;if(token!==version)return;for(const url of urls)URL.revokeObjectURL(url);urls=[];project=p;model=null;modelRevision=p?.modelRevision||1;dirty=false;$('model-save-status').textContent='';$('model-notes').textContent='';$('model-json').value='';for(const id of ['model-reference','model-source'])$(id).hidden=true;$('source-details').hidden=true;$('model-title').textContent=p?.name||'Dein interaktiver Grundriss';$('model-object').textContent=p?.listingRef?'Mit deinem gespeicherten Objekt verbunden.':'Ohne Objektzuordnung.';if(!p){if(viewer){viewer.destroy();viewer=null;viewerPromise=null}$('model-view').innerHTML='<p>Bitte eine gespeicherte Visualisierung auswählen.</p>';message('Bitte eine gespeicherte Visualisierung auswählen.');ready();return}const url=URL.createObjectURL(p.image);urls.push(url);$('model-reference').src=url;$('model-reference').hidden=false;if(p.source){const src=URL.createObjectURL(p.source);urls.push(src);$('model-source').src=src;$('model-source').hidden=false;$('source-details').hidden=false}$('model-consent').checked=false;ready();if(p.interactiveModel){try{await show(p.interactiveModel);message(modelRevision<2?'Älteres Modell geöffnet. Die neue zweistufige Rekonstruktion wird erst nach deinem Klick auf „Interaktives Modell ableiten“ verwendet.':'Gespeichertes Modell geöffnet.')}catch(e){message(e.message)}}else{message('Vorlagen prüfen und die kostenpflichtige Rekonstruktion starten.');if(viewer){viewer.destroy();viewer=null;viewerPromise=null}$('model-view').innerHTML='<p>Noch kein interaktives Modell für diese Visualisierung.</p>'}history.replaceState(null,'','?project='+encodeURIComponent(p.id))}
async function init(){try{projects=(await FloorplanStore.all()).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));for(const p of projects){const option=document.createElement('option');option.value=p.id;option.textContent=p.name+(p.interactiveModel?' · Modell gespeichert':'');$('model-project').append(option)}const requested=new URLSearchParams(location.search).get('project');if(requested&&projects.some(p=>p.id===requested)){$('model-project').value=requested;await loadProject(requested)}else if(projects.length===1){$('model-project').value=projects[0].id;await loadProject(projects[0].id)}else message('Eine gespeicherte Bildansicht auswählen.')}catch(e){message(e.message)}ready()}
$('model-project').onchange=()=>loadProject($('model-project').value).catch(e=>message(e.message));
$('model-form').onsubmit=async e=>{e.preventDefault();if(busy||!project||!$('model-form').reportValidity())return;if(model&&!confirm('Das bestehende Modell durch eine neue kostenpflichtige Rekonstruktion ersetzen?'))return;busy=true;ready();$('model-progress').hidden=false;$('model-login').hidden=true;message('Grundriss und Einrichtung werden rekonstruiert. Das kann mehrere Minuten dauern. Kein automatischer neuer Versuch.');try{let bearer=await FloorplanSession.access();const body=new FormData();body.append('image',project.source||project.image,'plan.jpg');if(project.source)body.append('reference',project.image,'render.jpg');body.append('height',String(project.settings?.height||2.5));body.append('style',project.settings?.style||'modern');body.append('notes',project.settings?.notes||'');body.append('consent','yes');const send=()=>fetch('/api/floorplan/model',{method:'POST',headers:{Authorization:'Bearer '+bearer},body,signal:AbortSignal.timeout(200000)});let r=await send();if(r.status===401){bearer=await FloorplanSession.access(true);r=await send()}const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Die Rekonstruktion konnte nicht abgeschlossen werden.');const next=validateModel(data.model);modelRevision=data.revision||1;dirty=true;await show(next);message('Modell erstellt. Bitte mit dem Original vergleichen, Maße korrigieren und speichern.');$('model-save-status').textContent='Noch nicht gespeichert.'}catch(e){if(e.code==='sign_in')$('model-login').hidden=false;message(e.name==='TimeoutError'?'Zeitüberschreitung. Eine API-Abrechnung kann trotzdem erfolgt sein. Vor einem erneuten Versuch prüfen.':e.message)}finally{busy=false;$('model-progress').hidden=true;ready()}};
$('model-save').onclick=async()=>{if(!project||!model||busy)return;try{const current=await FloorplanStore.get(project.id);if(!current)throw Error('Die zugehörige Visualisierung wurde entfernt.');project={...current,interactiveModel:validateModel(model),modelRevision,modelUpdatedAt:new Date().toISOString()};await FloorplanStore.put(project);dirty=false;$('model-save-status').textContent='Modell mit dem Objekt auf diesem Gerät gespeichert.'}catch(e){$('model-save-status').textContent=e.message}};
$('dimensions-form').onsubmit=async e=>{e.preventDefault();if(!model||busy||!$('dimensions-form').reportValidity())return;try{const next=validateModel({...model,width:Number($('model-width').value),depth:Number($('model-depth').value),height:Number($('model-height').value)});dirty=true;await show(next,false);$('model-save-status').textContent='Maße angepasst. Bitte Modell speichern.'}catch(e){$('model-save-status').textContent=e.message}};
$('apply-model-json').onclick=async()=>{if(busy)return;try{const next=validateModel(JSON.parse($('model-json').value));dirty=true;await show(next,false);$('model-save-status').textContent='Modelldaten übernommen. Bitte speichern.'}catch(e){$('model-save-status').textContent='Nicht übernommen: '+e.message}};
$('view-reset').onclick=()=>viewer?.reset();$('view-top').onclick=()=>viewer?.top();$('auto-rotate').onchange=()=>viewer?.rotate($('auto-rotate').checked);$('show-furniture').onchange=()=>viewer?.setFurniture($('show-furniture').checked);$('wall-cut').oninput=()=>{const n=Number($('wall-cut').value);$('wall-cut-label').textContent=n.toLocaleString('de-DE')+' m';viewer?.setCut(n)};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('model-export').onclick=()=>{if(model)download(new Blob([JSON.stringify(model,null,2)],{type:'application/json'}),'immobrain-3d-modell.json')};$('model-snapshot').onclick=async()=>{try{if(!viewer)throw Error('Bitte zuerst die 3D-Ansicht laden.');const blob=await viewer.snapshot();if(blob)download(blob,'immobrain-3d-ansicht.png')}catch(e){message(e.message)}};window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue=''}});init();
